<?php
$escape = static fn (mixed $value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8');
$url = static function (array $extra = []) use ($filters): string { $query = array_filter(array_merge($filters, $extra), static fn ($item) => $item !== '' && $item !== null); return 'tickets.php?' . http_build_query($query); };
$statusClass = static fn (string $status): string => strtolower(str_replace(' ', '-', $status));
?>
<section class="section"><header class="admin-header"><div><h1><?php echo $escape($scopeTitle); ?></h1><p><?php echo $escape($scopeDescription); ?></p></div><div class="ticket-header-actions"><a href="ticket_create.php" class="btn">Nuevo ticket</a><a href="customers.php" class="btn btn--secondary">Ver clientes</a></div></header><nav class="ticket-scope-tabs"><a href="<?php echo $escape($url(['scope' => 'open', 'page' => 1])); ?>" class="ticket-scope-tab <?php echo $isOpenScope ? 'ticket-scope-tab--active' : ''; ?>">Tickets abiertos</a><a href="<?php echo $escape($url(['scope' => 'all', 'page' => 1])); ?>" class="ticket-scope-tab <?php echo !$isOpenScope ? 'ticket-scope-tab--active' : ''; ?>">Todos los tickets</a></nav><div class="stats"><article class="stat-card"><i class="fas fa-life-ring stat-card__icon"></i><div class="stat-card__value"><?php echo (int) $ticketStats['total']; ?></div><p class="stat-card__label">Tickets</p></article><article class="stat-card"><i class="fas fa-hourglass-half stat-card__icon"></i><div class="stat-card__value"><?php echo (int) $ticketStats['open']; ?></div><p class="stat-card__label">Tickets abiertos</p></article><article class="stat-card"><i class="fas fa-user-friends stat-card__icon"></i><div class="stat-card__value"><?php echo (int) $ticketStats['customers']; ?></div><p class="stat-card__label">Clientes</p></article></div>
<div class="card panel-card"><form method="get" class="admin-form"><input type="hidden" name="scope" value="<?php echo $escape($filters['scope']); ?>"><div class="admin-form__row admin-form__row--triple"><div class="admin-form__group"><label class="admin-form__label" for="customer">Cliente</label><input id="customer" name="customer" class="admin-form__input" value="<?php echo $escape($filters['customer']); ?>"></div><div class="admin-form__group"><label class="admin-form__label" for="status">Estado</label><select id="status" name="status" class="admin-form__input"><option value="">Todos</option><?php foreach ($statuses as $status): ?><option value="<?php echo $escape($status); ?>" <?php echo $filters['status'] === $status ? 'selected' : ''; ?>><?php echo $escape($status); ?></option><?php endforeach; ?></select></div><div class="admin-form__group"><label class="admin-form__label" for="consultation_type">Tipo</label><select id="consultation_type" name="consultation_type" class="admin-form__input"><option value="">Todos</option><?php foreach ($types as $type): ?><option value="<?php echo $escape($type); ?>" <?php echo $filters['consultation_type'] === $type ? 'selected' : ''; ?>><?php echo $escape($type); ?></option><?php endforeach; ?></select></div></div><div class="admin-form__row admin-form__row--triple"><div class="admin-form__group"><label class="admin-form__label" for="assigned_user_id">Responsable</label><select id="assigned_user_id" name="assigned_user_id" class="admin-form__input"><option value="">Todos</option><option value="unassigned" <?php echo $filters['assigned_user_id'] === 'unassigned' ? 'selected' : ''; ?>>Sin responsable</option><?php foreach ($responsibleUsers as $user): ?><option value="<?php echo (int) $user['id']; ?>" <?php echo $filters['assigned_user_id'] === (string) $user['id'] ? 'selected' : ''; ?>><?php echo $escape($user['display_name'] ?: $user['username']); ?></option><?php endforeach; ?></select></div><div class="admin-form__group"><label class="admin-form__label" for="date_from">Desde</label><input id="date_from" type="date" name="date_from" class="admin-form__input" value="<?php echo $escape($filters['date_from']); ?>"></div><div class="admin-form__group"><label class="admin-form__label" for="per_page">Mostrar</label><select id="per_page" name="per_page" class="admin-form__input"><?php foreach ([10, 25, 50] as $size): ?><option value="<?php echo $size; ?>" <?php echo $perPage === $size ? 'selected' : ''; ?>><?php echo $size; ?> por página</option><?php endforeach; ?></select></div></div><button class="btn">Filtrar</button> <a href="tickets.php" class="btn btn--secondary">Limpiar</a></form></div>
<div class="ticket-toolbar"><div class="ticket-results-summary"><strong><?php echo (int) $total; ?></strong> tickets encontrados <span class="ticket-results-summary__page">Página <?php echo (int) $page; ?> de <?php echo (int) $totalPages; ?></span></div></div><div class="table-wrapper"><table class="table table--tickets"><thead><tr><th>Ticket</th><th>Cliente</th><th>Responsable</th><th>Precio</th><th>Estado</th><th>Cita</th><th>Canal</th><th>Contexto</th><th>Fecha</th><th>Acciones</th></tr></thead><tbody><?php if (!$tickets): ?><tr><td colspan="10">No se encontraron tickets con los filtros seleccionados.</td></tr><?php else: ?><?php foreach ($tickets as $ticket): ?><?php $ticketUrl = 'ticket_view.php?id=' . (int) $ticket['id'] . '&return=' . urlencode($url()); ?><tr><td><a href="<?php echo $escape($ticketUrl); ?>" class="ticket-primary-link">#<?php echo (int) $ticket['id']; ?></a><div class="ticket-meta"><?php echo $escape($ticket['consultation_type']); ?></div></td><td><strong><?php echo $escape($ticket['customer_name']); ?></strong><div class="ticket-meta"><?php echo $escape($ticket['customer_phone']); ?></div></td><td><?php echo $escape($ticket['assigned_display_name'] ?: $ticket['assigned_username'] ?: 'Sin responsable'); ?></td><td><?php echo $ticket['price_total_amount'] !== null ? '$' . number_format((float) $ticket['price_total_amount'], 2) . ' ' . $escape($ticket['price_currency'] ?: 'MXN') : 'Sin precio'; ?></td><td><span class="ticket-status ticket-status--<?php echo $escape($statusClass($ticket['status'])); ?>"><span class="ticket-status__dot"></span><?php echo $escape($ticket['status']); ?></span></td><td><?php echo $escape($ticket['appointment_date'] ?: 'Sin cita'); ?></td><td><?php echo $escape($ticket['origin_type']); ?></td><td><?php echo $escape($ticket['context_label'] ?: 'Sin contexto adicional'); ?></td><td><?php echo $escape(date('d/m/Y H:i', strtotime($ticket['created_at']))); ?></td><td><a href="<?php echo $escape($ticketUrl); ?>" class="table__action">Ver ticket</a></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div></section>
